/bin/zsh -lc "rtk python - <<'PY'
import json,sys,tempfile
from pathlib import Path
sys.path.insert(0,'scripts/release_checks')
from editor_host import NativeHost
from native_common import acceptance_model,ready,browser_kwargs,BrowserEvents
from playwright.sync_api import sync_playwright

probe = r'''()=>{
 const parse=value=>{const m=value.match(/rgba?\\\\((["'^)]+)'"\\\\)/);if("'!m)return null;const p=m[1].split('"',').map(v=>Number(v.trim()));return {r:p[0],g:p[1],b:p[2],a:p.length>3?p[3]:1};};
 const composite=(top,bottom)=>{if("'!top||top.a===0)return bottom;const a=top.a+(1-top.a)*bottom.a;return {r:(top.r*top.a+bottom.r*bottom.a*(1-top.a))/a,g:(top.g*top.a+bottom.g*bottom.a*(1-top.a))/a,b:(top.b*top.a+bottom.b*bottom.a*(1-top.a))/a,a};};
 const bg=node=>{const chain=[];for(let n=node;n;n=n.parentElement)chain.push(n);let value=parse(getComputedStyle(document.documentElement).backgroundColor)||{r:255,g:255,b:255,a:1};for(const n of chain.reverse())value=composite(parse(getComputedStyle(n).backgroundColor),value);return `rgb(${Math.round(value.r)}, ${Math.round(value.g)}, ${Math.round(value.b)})`;};
 const lum=value=>{const c=parse(value);const f=x=>{x/=255;return x<=.03928?x/12.92:Math.pow((x+.055)/1.055,2.4)};return .2126*f(c.r)+.7152*f(c.g)+.0722*f(c.b)};
 const ratio=(fg,bg)=>{const a=lum(fg),b=lum(bg);return (Math.max(a,b)+.05)/(Math.min(a,b)+.05)};
 const metrics=(node,name)=>{const s=getComputedStyle(node),fontSize=parseFloat(s.fontSize),weight=parseInt(s.fontWeight,10)||400,large=fontSize>=24||(fontSize>=18.66&&weight>=700),foreground=s.color,background=bg(node),threshold=large?3:4.5;return {name,foreground,background,font_size_px:fontSize,font_weight:weight,large_text:large,threshold,contrast:Number(ratio(foreground,background).toFixed(4)),count:1};};
 const items=[];
 for(const name of ['"'New report','Duplicate','Manage']){const nodes=[...document.querySelectorAll('.cui-visualizer-reportbar button')].filter(n=>n.textContent.trim()===name);if(nodes[0])items.push(metrics(nodes[0],name));}
 for(const value of ['84.2','42.8']){const nodes=[...document.querySelectorAll('.library-thumb .thumb-value')].filter(n=>n.textContent.trim()===value);if(nodes[0]){const row=metrics(nodes[0],"'`KPI thumbnail ${value}`);row.count=nodes.length;items.push(row);}}
 const palette=[...document.querySelectorAll('"'.pal-metric .pal-visual i')].filter(n=>n.textContent.trim()==='42.8')[0];if(palette)items.push(metrics(palette,'KPI quick-add 42.8'));
 return {theme:document.documentElement.dataset.theme||'system',items,reportbar_background:getComputedStyle(document.querySelector('.cui-visualizer-reportbar')).backgroundColor,root_accent:getComputedStyle(document.querySelector('.cui-visualizer-root')).getPropertyValue('--viz-accent').trim(),cui_accent:getComputedStyle(document.documentElement).getPropertyValue('--cui-accent').trim()};
}'''
with tempfile.TemporaryDirectory(prefix='visembler-contrast-after-') as td,NativeHost(Path.cwd(),Path(td)/'data') as host:
 host.create(model=acceptance_model(),name='contrast-after')
 with sync_playwright() as pw:
  browser=pw.chromium.launch(**browser_kwargs()); context=browser.new_context(); page=context.new_page(); events=BrowserEvents(); events.attach(page)
  results=[]
  for width,height in [(1440,1000),(390,844)]:
   page.set_viewport_size({'width':width,'height':height});page.goto(host.url+'/visualizer',wait_until='domcontentloaded');ready(page,require_settled=True)
   for theme in ('light','dark'):
    page.evaluate('(t)=>__VIZ_PROD__.setTheme(t)',theme);page.wait_for_timeout(120); row=page.evaluate(probe);row['viewport']={'width':width,'height':height};results.append(row)
  print(json.dumps({'results':results,'browser_errors':events.unexpected},indent=2));browser.close()
PY"

